class CppBeacon {
public:
    explicit CppBeacon(unsigned long intensity) : intensity_(intensity) {}
    unsigned long illuminate() const { return intensity_; }
private:
    unsigned long intensity_;
}

public sealed class CSharpBeacon {
    public ulong Intensity { get; }
    public CSharpBeacon(ulong intensity) => Intensity = intensity;
    public ulong Illuminate() => Intensity;
}

